script.text:
			/* <flatten type="Javascript"> */
function load$GridDetail$(g) {g.add_commandEvent(on$GridDetail$ExecuteCommand);}
function dispose$GridDetail$(g) {try {g.remove_commandEvent(on$GridDetail$ExecuteCommand);} catch (ex) {}}
/* </flatten> */
function on$GridDetail$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	var gls = f.getItem('ctdmku')._controlBehavior, v = f._language == 'v', id = g.get_id(), fid = f.get_id();
	switch (action) {
		&Clipboard.Event.Before;
		&Clipboard.Event.Before.Request;
		&Clipboard.Event.Before.Process;
		&Clipboard.Event.After;
		&Clipboard.Event.After.Process;
		&GridExtraToolbarExecuteCommandScript;
		case 'CalcInterest':
			if (f._action == 'View') break;
			var e0 = v ? 'Chưa nhập Thông tin lãi suất' : 'Interest rate is empty'
			 , e1 = v ? 'Chưa điền ngày vay' 'Loan date must not be empty'
			 , e2 = v ? 'Ngày hiệu lực từ/đến lồng nhau tại ngăn Thông tin lãi suất' : 'Effective date from/to overlap at Interest rate tab'
			 , e3 = v ? 'Không có lãi suất tương ứng cho Ngày thanh toán: %s' : 'Not found interest rate for Payment date: %s'
			 , e5 = v ? 'Đã xóa các dòng nằm ngoài <span class="Highlight">%s</span>' : 'Deleted rows out of <span class="Highlight">%s</span>'
			 , e6 = v ? 'Số lần thanh toán chưa nhập hoặc không hợp lệ' : 'Number of Payments is empty or invalid'
			 , e7 = v ? 'Số kỳ trả gốc chưa nhập hoặc không hợp lệ' : 'Number of Payments is empty or invalid';

			var toast = new $toast({
				message: "",
				duration: 5000,
				sticky: false
			});
			var mapls = [];
			//Kiểm tra Thông tin lãi suất ctdmku
			if (gls._rowCount == 0) {
				$message.show(e0, String.format('var f = $find(\'{0}\');f.focus(\'ctdmku\');', fid));
				break;
			} 
			//Kiểm tra Ngày vay ngay_ku1
			var ngay_vay_obj = f.getItem('ngay_ku1'), ngay_vay_date =  f.getItemValue('ngay_ku1'),  ngay_vay_value = ngay_vay_obj.value, ngay_vay_field = ngay_vay_obj.field;
				if (!ngay_vay_date ) {
				$message.show(e1, String.format('var f = $find(\'{0}\');f.focus(\'ngay_ku1\');', fid));
				break;
			}
			//Kiểm tra ngày overlap ngày hiệu lực lãi suất
			mapls = getEffectiveDateRangeMap(gls, 'ngay_hl', 'ngay_hl2', 'ls', true);

			if (checkOverlapDateRange(mapls, 0, 1)) {
				toast.message = e2;
				toast.show();
			}

			//Tính các kỳ thanh toán
			var tien = f.getItemValue('tien'), loai_tinh_lai = f.getItemValue('loai_tinh_lai'), so_ky_obj = f.getItem('sl_tt'),  ky_tra_no = f.getItemValue('ky_tra_no'), ky_tra_goc_obj = f.getItemValue('ky_tra_goc'), ky_tra_lai_obj = f.getItemValue('ky_tra_lai');
			var so_ky_value = so_ky_obj.value, so_ky_field = so_ky_obj.field;
			var ky_tra_goc_value = f.getItemValue('ky_tra_goc'), ky_goc_field = ky_tra_goc_obj.field;
			var ky_tra_lai_value = f.getItemValue('ky_tra_lai');
			//Kiểm tra số kỳ trả nợ
			if (so_ky_value <= 0) {
				toast.message = e6;
				toast.show();
				return;
			}
			if (ky_tra_goc_value <= 0 && loai_tinh_lai == 3 || loai_tinh_lai == 4) {
				toast.message = e7;
				toast.show();
				return;
			}
			var monthStep = 0;
			switch (ky_tra_no) {
				case 1: monthStep = 1;break; //tháng
				case 2: monthStep = 3;break; //quý
				case 3: monthStep = 6;break; //6 tháng
				case 4: monthStep = 12;break; //năm
				default: break;
			}
			var ngay_tt, ngay_tt_invalid = [];

			var tien_cl = tien;
			var  goc_moi_ky = 0, tien_tt = 0, tien_lai = 0, o;

			for (var i = 1; i<= so_ky_value; i++) {
				if (g._rowCount<i) {g._appendRow(null,true);}
				ngay_tt = dateAddMonth(ngay_vay_date, monthStep*i);
				ngay_tt.setDate(ngay_tt.getDate()-1);
				var ls_ref =  mapls.filter(function(row_ls) {return row_ls[0] <= ngay_tt && ngay_tt <= row_ls[1]} )[0];

				var ls_tam_tinh = ls_ref ? ls_ref[2] : null;
				if (!ls_tam_tinh) {
					ngay_tt_invalid.push($func.valueToFormatString(ngay_tt, ngay_vay_field.DataFormatString, ngay_vay_field, true));
					continue;
				}
				o = g._getItem(i, 1);
				o.row = i;


				//Xử lý nghiệp vụ
				var so_ky_ls = Math.ceil(preciseMonthDiff(ls_ref[0], ls_ref[1]));


				var ls_tam_tinh = ls_tam_tinh/1200*monthStep;

				if (loai_tinh_lai==1) //Dư nợ giảm dần (Reducing Balance)
				{
					goc_moi_ky = tien / so_ky_value;
					tien_lai = tien_cl* ls_tam_tinh;
					tien_tt = goc_moi_ky + tien_lai;
					tien_cl -= goc_moi_ky
				}

				if (loai_tinh_lai == 3) //Dư nợ giảm dần có kỳ ân hạn
					{
							if (i < ky_tra_goc_value) {
									goc_moi_ky = 0;
							} else {
									goc_moi_ky = tien / (so_ky_value - ky_tra_goc_value + 1);
									tien_cl -= goc_moi_ky;
							}
							if (i < ky_tra_lai_value) {
									tien_lai = 0;
							} else {
									tien_lai = tien_cl * ls_tam_tinh;
							}
								tien_tt = goc_moi_ky + tien_lai;
					}

					if (loai_tinh_lai == 4) //Dư nợ giảm dần có kỳ ân hạn
					{
							if (i < ky_tra_goc_value) {
									goc_moi_ky = 0;
							} else {
									goc_moi_ky = tien / (so_ky_value - ky_tra_goc_value + 1);
									tien_cl -= goc_moi_ky;
							}
							if (i < ky_tra_lai_value) {
									tien_lai = 0;
							} else {
									tien_lai = tien_cl * ls_tam_tinh;
							}
								tien_tt = goc_moi_ky + tien_lai;
					}

				if (loai_tinh_lai==2) //Cố định tổng thanh toán (Fixed Installment)
				{
					so_ky_ls = so_ky_value;			
					tien_lai = calIPMT(ls_tam_tinh, i, so_ky_ls, tien);
					goc_moi_ky = calPPMT(ls_tam_tinh, i, so_ky_ls, tien);
					tien_tt = calcPMT(ls_tam_tinh, so_ky_ls, tien);
					tien_cl -= goc_moi_ky;
					if (tien_cl < 0) {
						goc_moi_ky += tien_cl;
						tien_tt += tien_cl;
						tien_cl = 0;
					}
				}

				g.setItemGridBehavior(o, [
					['ngay_tt', ngay_tt, '', null],
					['ls_tam_tinh', ls_tam_tinh*100, null, null], 
					['tien_goc_cl', tien_cl, null, null],
					['tien_goc_tk', goc_moi_ky, null, null],
					['tien_lai_tk', tien_lai, null, null],
					['tt', tien_tt, null, null]
				]); 
			}
			//Kiểm tra các ngày thanh toán ko có lãi suất tương ứng
			if (ngay_tt_invalid.length > 0) {
				toast.message = e3.replace('%s', '\n'+ ngay_tt_invalid.join('\n'));
				toast.show();
			} 

			//Xóa các dòng vượt hạn thanh toán
			if (so_ky_value<g._rowCount) {
				deleteRedundant(g, o.row);
				//toast.message = e5.replace('%s', so_ky_field.HeaderText);
				//toast.show();
				//$message.show(e5.replace('%s', so_ky_field.HeaderText), 0, String.format('deleteRedundant($find(\'{0}\'), \'{1}\', \'ngay_tt\')', id, ngay_tt.toISOString()), ''); 
			}
			break;
		default:
			break;
	}
}
function calcPMT(rate, nper, pv) {
	return pv * rate * Math.pow(1 + rate, nper) / (Math.pow(1 + rate, nper) - 1);
}
function calIPMT(rate, per, nper, pv) {
	var pmt = calcPMT(rate, nper, pv);
	var balanceBefore = pv * Math.pow(1 + rate, per - 1)  - pmt * ((Math.pow(1 + rate, per - 1) - 1) / rate);
	return balanceBefore * rate;
}
function calPPMT(rate, per, nper, pv) {
	return calcPMT(rate, nper, pv) - calIPMT(rate, per, nper, pv);
}
function deleteRedundant(g, lastRow) {
	for (var i = g._rowCount; i>lastRow;i--) {
		g._setActiveCell(g._getItem(i, 1))
		g._deleteRow(); 			
	}
	g._setActiveCell(g._getItem(g._rowCount, 1));
}
function dateAddMonth(date, monthsToAdd) {
	var d = new Date(date);
	var day = d.getDate();
	d.setMonth(d.getMonth() + monthsToAdd);
	if (d.getDate() < day) {
			d.setDate(0); 
	}
	return d;
}
function preciseMonthDiff(startDate, endDate) {
	var start = new Date(startDate);
	var end = new Date(endDate);

	if (start > end) return -preciseMonthDiff(end, start); 
	var startY = start.getFullYear(), startM = start.getMonth(), startD = start.getDate();
	var endY = end.getFullYear(), endM = end.getMonth(), endD = end.getDate();
	var months = (endY - startY) * 12 + (endM - startM);
	var base = new Date(start);
	base.setMonth(base.getMonth() + months);
	if (base > end) {
			months--;
			base.setMonth(base.getMonth() - 1);
	}
	var nextMonth = new Date(base);
	nextMonth.setMonth(base.getMonth() + 1);
	var fraction = (end - base) / (nextMonth - base);
	return months + fraction;
}

			&GridExtraToolbarScript;
